const items = $input.all();
if (!items.length || !items[0].json || !items[0].json.habit_id) {
    return [];
}

const now = new Date();
// Cairo/KSA local hour (UTC+3)
const localHour = (now.getUTCHours() + 3) % 24;
const currentHourStr = `${String(localHour).padStart(2, '0')}:00`;
const todayStr = now.toISOString().split('T')[0];

// Filter habits due at current hour that have not been logged today
const dueHabits = items.map(i => i.json).filter(h => {
    const reminder = (h.reminder_time || '').trim();
    const snooze = (h.snooze_until || '').trim();
    const isDue = (reminder === currentHourStr || snooze === currentHourStr);
    const notDoneToday = (h.last_completed_date !== todayStr);
    return isDue && notDoneToday;
});

if (dueHabits.length === 0) {
    return [];
}

// Group by telegram_chat_id for Smart Batching
const userGroups = {};
dueHabits.forEach(h => {
    const chatId = h.telegram_chat_id;
    if (!chatId) return;
    if (!userGroups[chatId]) userGroups[chatId] = [];
    userGroups[chatId].push(h);
});

const output = [];

for (const [chatId, habits] of Object.entries(userGroups)) {
    let text = `🎯 *حان وقت عاداتك لليوم (الساعة ${currentHourStr}):*\n\n`;
    const keyboardRows = [];

    habits.forEach((h, idx) => {
        const streak = h.current_streak ? ` — Streak: ${h.current_streak} 🔥` : '';
        text += `${idx + 1}. ✨ *${h.habit_name}* (${h.target_minutes || 15} دقيقة)${streak}\n`;
        keyboardRows.push({
            row: {
                buttons: [
                    {
                        text: `✅ أنجزت: ${h.habit_name}`,
                        additionalFields: {
                            callback_data: `done_habit__${h.habit_id}`
                        }
                    }
                ]
            }
        });
    });

    // General snooze row
    keyboardRows.push({
        row: {
            buttons: [
                {
                    text: `⏳ تأجيل التذكير ساعة`,
                    additionalFields: {
                        callback_data: `snooze__${habits[0].habit_id}`
                    }
                }
            ]
        }
    });

    output.push({
        json: {
            chat_id: chatId,
            message_text: text,
            keyboard_rows: keyboardRows
        }
    });
}

return output;
